const d = items[0]?.json || {};
const orgs = d.organizations || {};
const projects = d.projects || {};
const tasks = d.tasks || {};
const pipeline = d.pipeline || [];
const lines = [
  'KingDesign Collective — Daily Executive Report',
  '—'.repeat(40),
  `Organizations: ${orgs.total || 'N/A'} total (${orgs.subsidiaries || 0} subsidiaries, ${orgs.active || 0} active)`,
  `Projects: ${projects.active || 0} active, ${projects.blocked || 0} blocked`,
  `Tasks: ${tasks.in_progress || 0} in_progress, ${tasks.blocked || 0} blocked`,
  '',
  'Pipeline (active + blocked):'
];
pipeline.slice(0, 10).forEach(p => {
  lines.push(`  [${p.priority || 'N/A'}] ${p.name} — ${p.company_id} (${p.status})`);
});
if (pipeline.length === 0) lines.push('  (empty)');
lines.push('', 'Run `kd ask "<question>"` for details.');
return [{json: {report: lines.join('\n')}}];
